} catch (e) {
    try {
        device = java.deviceID();
        device_type = '苹果';
    } catch (e) {
        device = '';
        device_type = '安卓';
    }
}
if (device_type=='安卓') {
	data = {'content':`【右上角刷新】开启播放(下一集请切换下一章刷新)\n播放直链：${content}`}
	data = JSON.stringify(data);
