	 let 	book_id = java.get('book_id');
	 let sources = java.get('sources');
		let video_url = `http://113.45.175.112:8888/online_video?book_id=${book_id}&source=${sources}&tab=短剧`;
  	java.startBrowser(video_url,'短剧');
	 	java.toast('正在加载视频...');
	};
	} else {
		data = {'content':content}
	data = JSON.stringify(data);
		}
data;
