var JMHS='www.cdngwc.cc,www.cdnhjk.net,www.cdngwc.net,www.cdngwc.club';
var JMIMS='cdn-msp.jmapiproxy1.cc,cdn-msp.jmapiproxy2.cc,cdn-msp2.jmapiproxy2.cc,cdn-msp.jmapinodeudzn.net';
var JMSC=220980;
var JMSC2=268850;
var JMSC3=421926;
function gv(o,k){try{var f=o[k];return typeof f==='function'?f.call(o):f;}catch(e){return null;}}
function jmg(sv,k){try{var v=sv.get(k);if(v==null)return null;var s=String(v);if(s.length<1)return null;return s;}catch(e){return null;}}
function jmp(sv,k,v){try{sv.put(k,String(v));}catch(e){}}
function jmts(sv){var t=jmg(sv,'jmts');if(t==null||t.length<5){t=String(Math.floor(Date.now()/1000));jmp(sv,'jmts',t);}return t;}
function jmnewts(sv){var t=String(Math.floor(Date.now()/1000));jmp(sv,'jmts',t);return t;}
function jmhost(sv){var h=jmg(sv,'jmh');if(h==null){return 'www.cdngwc.cc';}return h;}
function jmimg(sv){var h=jmg(sv,'jmim');if(h==null){return 'cdn-msp.jmapiproxy1.cc';}return h;}
