function jmdec(jv,s,t){try{return String(jv.aesBase64DecodeToString(String(s),String(jv.md5Encode(t+JMS)),'AES/ECB/PKCS5Padding',''));}catch(e){return null;}}
function jmhead(jv,sv,t,sec){var o={};o.token=String(jv.md5Encode(t+(sec||JMS)));o.tokenparam=t+','+JMV;o['user-agent']=JMU;o['X-Requested-With']='com.JMComic3.app';o['Content-Type']='application/x-www-form-urlencoded';return o;}
function jmpost(jv,u,b,hd){var hs=String(JSON.stringify(hd));
 try{return jv.post(String(u),String(b),hs);}catch(e1){}
 try{var m=new Packages.java.util.HashMap();
  m.put('token',String(hd.token));m.put('tokenparam',String(hd.tokenparam));m.put('user-agent',String(hd['user-agent']));m.put('X-Requested-With',String(hd['X-Requested-With']));m.put('Content-Type',String(hd['Content-Type']));
  return jv.post(String(u),String(b),m);
 }catch(e2){return null;}
}
function jmget(jv,sv,path,post,body){var h=jmhost(sv);var tries=0;var ts=jmts(sv);var last=null;
 for(var r=0;r<2;r++){
  try{
   var hd=jmhead(jv,sv,ts,JMS);
   var resp=null;
   if(post){resp=jmpost(jv,'https://'+h+path,body||'',hd);}
   else{resp=jv.connect(String('https://'+h+path),String(JSON.stringify(hd)));}
   if(resp==null){throw 'resp null';}
   var b=String(gv(resp,'body'));
   var o=JSON.parse(b);
   if(o&&o.code===200){
    var d=o.data;var s=String(d);
    if(s.length>1){
     if(s.charAt(0)!=='{'&&s.charAt(0)!=='['){s=jmdec(jv,s,ts);if(s==null||s.length<1){throw 'dec fail';}}
    } else {s='{}';}
    return JSON.parse(s);
   }
   if(o&&o.code===401){throw '401';}
   last='code '+o.code;
  }catch(e){last=String(e);if(String(e).length>220)last='net: '+String(e).substring(0,100);}
  ts=jmnewts(sv);
 }
 return null;
}
function jmcat(jv,sv,o){var out=[];
 try{
  var host=jmhost(sv);var imgH=jmimg(sv);
  var qj=String.fromCharCode(123,34,104,101,97,100,101,114,115,34,58);
  var cont=o&&o.content?o.content:(o&&o.list?o.list:null);
  if(cont==null)return out;
  for(var i=0;i<cont.length;i++){
   var c=cont[i];var id=String(c.id||'');
   if(id.length<1)continue;
   var n=String(c.name||'未知标题');
   var au=String(c.author||'');
   var hdo={};hdo['user-agent']=JMU;hdo['X-Requested-With']='com.JMComic3.app';
   var cv='https://'+imgH+'/media/albums/'+id+'_3x4.jpg?v=1'+','+qj+JSON.stringify(JSON.stringify(hdo))+'}}';
   var ep=c.latest_ep?String(c.latest_ep):'';
   out.push(String(JSON.stringify({name:n,author:au,aid:id,url:'https://'+host+'/album?id='+id,cover:cv,ep:ep})));
