function jmnum(jv,aid,fn){aid=parseInt(aid,10)||0;
 if(aid<JMSC)return 0;
 if(aid<JMSC2)return 10;
 var x=aid<JMSC3?10:8;
 var h=String(jv.md5Encode(String(aid)+String(fn)));
 var c=h.charCodeAt(h.length-1);
 return (c%x)*2+2;
}
