(function(){var out=[];
 try{
  var host=jmhost(source);
  function aidOf(bu){var i=String(bu).indexOf('id=');if(i<0)return '';var t=String(bu).substring(i+3);var j=0;while(j<t.length){var ch=t.charAt(j);if(ch>='0'&&ch<='9'){j++;}else{break;}}return t.substring(0,j);}
  var aid='';
  try{aid=aidOf(baseUrl);}catch(e){}
  if(aid.length<1){try{aid=aidOf(book?book.tocUrl:'');}catch(e2){}}
  var obj=null;
  var cache=jmg(source,'jmalb_'+aid);
  if(cache!=null){try{obj=JSON.parse(cache);}catch(e){obj=null;}}
  if(obj==null){
   obj=jmget(java,source,'/album?id='+aid);
   if(obj!=null){jmp(source,'jmalb_'+aid,JSON.stringify({id:aid,name:String(obj.name||''),author:'',tags:'',series:(obj.series||[]),desc:'',imgH:jmimg(source)}));}
  }
  if(obj==null){out.push(String(JSON.stringify({n:'目录获取失败：详情缓存丢失，请回到详情页刷新',cid:'https://'+host+'/chapter?id=0'})));return out;}
  var ser=obj.series||[];
  var bookName=String(obj.name||'');
  var i=0;
  if(ser.length<1){
   out.push(String(JSON.stringify({n:bookName.length?bookName:'全一话',cid:'https://'+host+'/chapter?id='+aid})));
  } else {
   for(i=0;i<ser.length;i++){var p=ser[i];var pid=String(p.id||'');if(pid.length<1)continue;out.push(String(JSON.stringify({n:String(p.name||('第'+i+'话')),cid:'https://'+host+'/chapter?id='+pid})));}
  }
 }catch(e){out=[];}
 return out;
})()

